    private static void changeIncoming(LivingIncomingDamageEvent event){if(!selected(event.getEntity()))return;require(event.getSource().getEntity()==player,"Actual attack retains real ServerPlayer source");rawIncoming=event.getAmount();if(mode.equals("incoming-cancel"))event.setCanceled(true);if(mode.equals("incoming-half"))event.setAmount(event.getAmount()*0.5F);}
