    private static void pre(LivingDamageEvent.Pre event){record("pre",event.getEntity(),event.getNewDamage());if(preparing())return;if(selected(event.getEntity())){observedReductions.clear();for(Reduction reduction:Reduction.values())observedReductions.put(reduction.toString(),event.getContainer().getReduction(reduction));originalReducedBudget=acceptedBeforeMitigation;for(Reduction reduction:List.of(Reduction.ARMOR,Reduction.ENCHANTMENTS,Reduction.MOB_EFFECTS,Reduction.INNATE_RESISTANCE))originalReducedBudget-=event.getContainer().getReduction(reduction);require(Float.isFinite(originalReducedBudget)&&originalReducedBudget>=0.0F,"Original accepted raw less native armor/magic reductions gives finite sharing budget");require(event.getSource().getEntity()==player&&event.getSource().getDirectEntity()==player,"Direct real player attack has no spell-cap path");}}
