    private static void cleanStack()throws Exception{for(EasterBossEntity entity:known.values())require(((NativeManorDamageScopeAccess)entity).ftboss$manorDamageContainers().isEmpty(),"Every actual Boss/helper stack restored");Field field=NativeManorDamageBridge.class.getDeclaredField("FRAMES");field.setAccessible(true);require(((ThreadLocal<?>)field.get(null)).get()==null,"No leaked native invocation frame");}
