        try{row.put("originalAttackValue",value);row.put("originalAttackModifiers",attribute.getModifiers().stream().map(Object::toString).toList());double lower=-1000000000.0D,upper=1000000000.0D;attribute.setBaseValue(lower);double minimum=attribute.getValue();attribute.setBaseValue(upper);double maximum=attribute.getValue();row.put("calibrationRange",List.of(minimum,maximum));require(Double.isFinite(minimum)&&Double.isFinite(maximum)&&minimum<desired&&maximum>=desired,"Unchanged original modifiers admit desired actual attack value");for(int iteration=0;iteration<64;iteration++){double midpoint=lower+(upper-lower)*0.5D;attribute.setBaseValue(midpoint);if(attribute.getValue()<desired)lower=midpoint;else upper=midpoint;}attribute.setBaseValue(lower+(upper-lower)*0.5D);require(Math.abs(attribute.getValue()-desired)<0.01D,"Only public attack base calibrated; original effects/modifiers retained");row.put("actualAttackAttribute",attribute.getValue());row.put("originalAttackBase",base);observing=true;try{player.attack(attackTarget);}finally{observing=false;}}finally{attribute.setBaseValue(base);for(var entry:positions.entrySet())if(!entry.getKey().isRemoved())entry.getKey().setPos(entry.getValue());for(var entry:invulnerable.entrySet())if(!entry.getKey().isRemoved())entry.getKey().setInvulnerable(entry.getValue());}
