    private static void serverTick(ServerTickEvent.Post event){if(finished.get()||!clientReady)return;try{require(++serverTicks<1800,"Bounded natural server observation");if(player==null){var players=event.getServer().getPlayerList().getPlayers();if(players.isEmpty())return;player=players.getFirst();setup();return;}require(player.isAlive(),"Actual player remains alive");if(acquisitionRetiring){if(level.getGameTime()-acquisitionRetiredAt>=40){require(!ManorFight.hasActive(level)&&!ManorFight.isPlayerFighting(player)&&primary.isRemoved(),"Original failed acquisition cleanup complete before next legitimate egg");setup();}return;}if(surrendered){if(level.getGameTime()-surrenderAt>=40){require(!ManorFight.hasActive(fight)&&!ManorFight.isPlayerFighting(player)&&primary.isRemoved(),"Original fight authority and primary cleanup remain complete after 40 natural ticks");cleanStack();report.put("actualReducedBudgetManagedSharingMatrixAccepted",true);report.put("originalRegisteredEggIngressAndDuplicateGuardAccepted",true);report.put("naturalOriginalMiniSummonsAccepted",true);report.put("originalGuardedSurrenderCleanupAccepted",true);finish(null);}return;}if(setupDone&&level.getGameTime()-lastAction>=actionDelay)exercise();}catch(Throwable failure){finish(failure);}}
